//! One leading literal escaped colon in EXT class identifiers only.
use kobo_web_document::{Limits,SupplyBudget,SnapshotState,HistoryState,InputState,FocusState,TargetState};
fn snap()->SnapshotState{SnapshotState{history:None,input:None,focus:None,target:None}}
fn run(c:&str,b:&str,l:&Limits,s:&SnapshotState)->kobo_web_document::style_tree::StyleTree{let h=format!("<!doctype html><style>{c}</style>{b}");kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],l,None,SupplyBudget::CANONICAL,s)}
#[test] fn browser_color_rank9(){let h=include_str!("fixtures/leading_class_colon_cascade.html");let t=kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],&Limits::DEFAULT,None,SupplyBudget::CANONICAL,&snap());assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().filter(|n|n.tag=="div").map(|n|n.style.color).collect::<Vec<_>>(),[0x0000ff,0xff0000,0x0000ff,0xff0000,0x0000ff,0x0000ff,0x0000ff,0x0000ff,0x0000ff]);}
#[test] fn state_families_target_autofocus_and_partial_loss(){let c=r".absent:has(.\:focus:where(:not(:focus))){color:red}";let b="<div><b class=':focus'></b></div>";let mut s=snap();assert!(run(c,b,&Limits::DEFAULT,&s).unsupported);s.history=Some(HistoryState::FreshNoHistory);s.input=Some(InputState::QuiescentCapture);assert!(run(c,b,&Limits::DEFAULT,&s).unsupported);s.focus=Some(FocusState::UnfocusedInitial);assert!(!run(c,b,&Limits::DEFAULT,&s).unsupported);assert!(run(c,"<div><b class=':focus' autofocus></b></div>",&Limits::DEFAULT,&s).unsupported);s.target=Some(TargetState::Fragment("tail".into()));let t=run(r".\:focus:target{color:red}","<div id=tail class=':focus'></div>",&Limits::DEFAULT,&s);assert!(!t.unsupported);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,0xff0000);for q in [r":where(.\:focus)",r":not(.\:focus)",r"div:has(.\:focus)"]{for l in [Limits{max_input_bytes:50,..Limits::DEFAULT},Limits{max_nodes:1,..Limits::DEFAULT},Limits{max_text_bytes:0,..Limits::DEFAULT}]{let t=run(&format!("{q}{{color:red}}"),"<div><b class=':focus'>text</b></div>",&l,&snap());assert!(t.unsupported||t.truncated);}}}
#[test] fn long_class_bytework_and_aggregate_global_work(){let b=format!("<div class='{}'></div>","a!y ".repeat(500));let t=run(r":not(.\:focus):not(.\:focus):not(.\:focus){color:red}",&b,&Limits::DEFAULT,&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);let one=format!("<div class='{}'></div>","a ".repeat(100));let q=r":where(.\:focus){color:red}";assert!(!run(q,&one,&Limits::DEFAULT,&snap()).truncated);let t=run(&q.repeat(100),&one.repeat(200),&Limits::DEFAULT,&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);assert_eq!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::DomNodes),0);}
#[test] fn default_and_other_identifier_isolation_attribute_loss(){let h=r"<!doctype html><style>.\:focus{color:red}</style><div class=':focus'></div>";let t=kobo_web_document::parse_style_tree(h.as_bytes(),&[],&Limits::DEFAULT);assert!(t.unsupported);for q in [r"#a\!x",r"a\!x",r"[a\!x]",r"[a=a\!x]",r":a\!x"]{assert!(run(&format!("{q}{{color:red}}"),"<div class=':focus'></div>",&Limits::DEFAULT,&snap()).unsupported);}let b=format!("<div {} class=':focus'></div>",(0..40).map(|i|format!("data-x{i}=a ")).collect::<String>());let t=run(r"div:has(.\:focus){color:red}",&b,&Limits::DEFAULT,&snap());assert!(t.diagnostics.dropped_attributes>0&&t.truncated,"retained diagnostic tree partial, no universal enrollment invalidation");assert!(!t.unsupported,"class-only enrollment unchanged, not silent complete page");}
#[test] #[ignore="measurement: LEADING_CLASS_COLON_LINES original2 under BOTH explicit guarantees"] fn original2_public_inventory(){let text=std::fs::read_to_string(std::env::var("LEADING_CLASS_COLON_LINES").unwrap()).unwrap();let mut total=0;for(i,l)in text.lines().enumerate(){total+=1;let cls=l.split(':').next().unwrap().strip_prefix('.').unwrap();let mut s=snap();s.input=Some(InputState::QuiescentCapture);s.focus=Some(FocusState::UnfocusedInitial);for(has,v)in[(false,0xff0000),(true,0x000000)]{let t=run(&format!("{l}{{color:red}}"),&format!("<div class='{cls}{}'></div>",if has{" :focus"}else{""}),&Limits::DEFAULT,&s);assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,v);}for partial in [snap(),SnapshotState{input:Some(InputState::QuiescentCapture),..snap()},SnapshotState{focus:Some(FocusState::UnfocusedInitial),..snap()}]{let t=run(&format!(".absent{l}{{color:red}}"),"<div></div>",&Limits::DEFAULT,&partial);assert!(t.unsupported);}assert!(run(&format!("{l}{{color:red}}"),&format!("<div class='{cls}' autofocus></div>"),&Limits::DEFAULT,&s).unsupported);println!("LEADING-COLON-PUBLIC line={} enrolled=true positive=true negative=true missing_and_single_family_refused=true autofocus_refused=true",i+1);}assert_eq!(total,2);println!("LEADING-COLON-PUBLIC total=2 passed=2");}

#[test] fn same_browser_original_html_replay_under_explicit_dual_contract(){let h=include_str!("fixtures/leading_class_colon_original_browser.html");let mut s=snap();s.input=Some(InputState::QuiescentCapture);s.focus=Some(FocusState::UnfocusedInitial);for(q,w)in[(r".govuk-skip-link:not(:active):not(:focus):not(.\:focus)",[0xff0000,0,0,0]),(r".govuk-visually-hidden-focusable:not(:active):not(:focus):not(.\:focus)",[0,0,0xff0000,0])]{let t=run(&format!("{q}{{color:red}}"),h,&Limits::DEFAULT,&s);assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().filter(|n|n.tag=="div").map(|n|n.style.color).collect::<Vec<_>>(),w);}}
